def square_matrix(mat):
    return torch.matmul(mat, mat.adjoint())


def _run_case(test, scenario, band, elevation, direction):
    channel_model = _build_model(scenario, band, elevation, direction)
    squared = square_matrix(channel_model._lsp_sampler._cross_lsp_correlation_matrix_sqrt)
    los = channel_model._scenario.los
    mats = {"los": squared[los], "nlos": squared[los == False]}
    cell = _EXPECTED[(scenario, band, elevation, direction)]
    for (block, i, j, cname) in _STRUCTURE:
        const = 1.0 if cname == "DIAG" else cell[cname]
        within = torch.abs(mats[block][:, i, j] - const) <= 0.0001
        assert torch.all(within), (
            f"{cname} @ {block}[{i},{j}] {scenario}/{band}/{elevation}deg/{direction}")


def _make_case(scenario, band, elevation, direction):
    def test(self):
        _run_case(self, scenario, band, elevation, direction)
    return test


def _populate(cls, scenario):
    for band in _BANDS:
        for elevation in _ELEVS:
            for dtok, direction in _DIRS:
                name = f"test_{band}_{elevation}_degrees_{dtok}"
                case = _make_case(scenario, band, elevation, direction)
                if (scenario, band, elevation, direction) in _TOPO:
                    case = pytest.mark.slow(case)  # larger topology
                setattr(cls, name, case)


class Test_URB(unittest.TestCase):
    pass


class Test_DUR(unittest.TestCase):
    pass


class Test_SUR(unittest.TestCase):
    pass


_populate(Test_URB, "urb")
_populate(Test_DUR, "dur")
_populate(Test_SUR, "sur")


if __name__ == "__main__":
    unittest.main()

